package com.eidolon.sc.mobile;

import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import android.graphics.*;import android.net.Uri;
import androidx.exifinterface.media.ExifInterface;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;

/** Shared, content-addressed private files. Removing a sticker never removes history's asset. */
final class MediaStore {
    static final int MAX_IMAGE=1536*1024,MAX_IMPORT=12*1024*1024,MAX_BACKUP=12*1024*1024;
    static void create(SQLiteDatabase db){
        db.execSQL("ALTER TABLE messages ADD COLUMN content TEXT NOT NULL DEFAULT '[]'");
        db.execSQL("CREATE TABLE media_assets(id TEXT PRIMARY KEY,mime TEXT NOT NULL,bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL)");
        db.execSQL("CREATE TABLE stickers(id TEXT PRIMARY KEY,asset TEXT NOT NULL,body TEXT NOT NULL)");
        db.execSQL("CREATE TABLE media_profiles(character TEXT PRIMARY KEY,body TEXT NOT NULL)");
        db.execSQL("CREATE TABLE media_analysis(id TEXT PRIMARY KEY,body TEXT NOT NULL)");
    }
    static File file(Context c,String id,boolean thumb)throws Exception{if(!MediaData.hash(id))throw new IOException("媒体编号无效");File dir=new File(c.getFilesDir(),"chat-media");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("媒体目录不可用");return new File(dir,id+(thumb?".thumb.webp":".bin"));}
    static void atomic(File f,byte[] bytes)throws Exception{File tmp=File.createTempFile("media-",".tmp",f.getParentFile());try{try(FileOutputStream out=new FileOutputStream(tmp)){out.write(bytes);out.getFD().sync();}Files.move(tmp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{if(tmp.exists())tmp.delete();}}
    static JSONObject asset(ChatStore s,String id)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT mime,bytes,width,height FROM media_assets WHERE id=?",new String[]{id})){if(!r.moveToFirst())throw new IOException("图片资源不存在");return new JSONObject().put("id",id).put("mime",r.getString(0)).put("bytes",r.getLong(1)).put("width",r.getInt(2)).put("height",r.getInt(3));}}
    static InputStream open(Context c,ChatStore s,String id,boolean thumb)throws Exception{asset(s,id);File f=file(c,id,thumb);if(!f.exists()&&thumb)f=file(c,id,false);return new FileInputStream(f);}
    static JSONObject importImage(Context c,ChatStore s,Uri uri)throws Exception{
        byte[] raw;try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取图片");raw=StoryFiles.read(in,MAX_IMPORT);}
        JSONObject result=importImage(c,s,raw);result.remove("newAsset");return result;
    }
    static JSONObject importImage(Context c,ChatStore s,byte[] raw)throws Exception{
        if(raw==null||raw.length==0||raw.length>MAX_IMPORT)throw new IOException("图片文件过大或为空");
        BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,o);
        if(o.outWidth<=0||o.outHeight<=0||(long)o.outWidth*o.outHeight>80000000L)throw new IOException("图片损坏或像素过大");
        String source=o.outMimeType;if(!Arrays.asList("image/png","image/jpeg","image/webp","image/gif").contains(source))throw new IOException("支持PNG、JPG、WEBP和GIF首帧");
        o.inJustDecodeBounds=false;o.inSampleSize=1;while((long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>6000000L||Math.max(o.outWidth,o.outHeight)/o.inSampleSize>4096)o.inSampleSize*=2;
        Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,o);if(bitmap==null)throw new IOException("图片解码失败");
        try{
            try{int orientation=new ExifInterface(new ByteArrayInputStream(raw)).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(orientation){case 2:m.setScale(-1,1);break;case 3:m.setRotate(180);break;case 4:m.setScale(1,-1);break;case 5:m.setRotate(90);m.postScale(-1,1);break;case 6:m.setRotate(90);break;case 7:m.setRotate(-90);m.postScale(-1,1);break;case 8:m.setRotate(-90);break;}if(!m.isIdentity()){Bitmap next=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),m,true);if(next!=bitmap){bitmap.recycle();bitmap=next;}}}catch(IOException ignored){}
            int[] fit=MediaData.fitSize(bitmap.getWidth(),bitmap.getHeight());if(fit[0]!=bitmap.getWidth()||fit[1]!=bitmap.getHeight()){Bitmap next=Bitmap.createScaledBitmap(bitmap,fit[0],fit[1],true);bitmap.recycle();bitmap=next;}
            byte[] normalized;boolean alpha=bitmap.hasAlpha()||"image/png".equals(source)||"image/gif".equals(source);String mime=alpha?"image/png":"image/jpeg";
            for(;;){ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(alpha?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,92,out);normalized=out.toByteArray();if(normalized.length<=MAX_IMAGE)break;if(Math.max(bitmap.getWidth(),bitmap.getHeight())<500)throw new IOException("图片压缩后仍过大");Bitmap next=Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(bitmap.getWidth()*.8)),Math.max(1,(int)(bitmap.getHeight()*.8)),true);bitmap.recycle();bitmap=next;}
            String id=MediaData.hash(normalized);SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{
                boolean newAsset=!exists(s,id);
                try(Cursor r=db.rawQuery("SELECT coalesce(sum(bytes),0),count(*) FROM media_assets",null)){r.moveToFirst();if(!exists(s,id)&&(r.getLong(0)+normalized.length>64*1024*1024L||r.getInt(1)>=2000))throw new IOException("本机媒体库已达64MB或2000张限制");}
                File f=file(c,id,false);if(!f.exists())atomic(f,normalized);
                int w=bitmap.getWidth(),h=bitmap.getHeight();double scale=Math.min(1,256.0/Math.max(w,h));Bitmap thumb=Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)),true);
                ByteArrayOutputStream out=new ByteArrayOutputStream();thumb.compress(Bitmap.CompressFormat.WEBP,85,out);atomic(file(c,id,true),out.toByteArray());if(thumb!=bitmap)thumb.recycle();
                ContentValues v=new ContentValues();v.put("id",id);v.put("mime",mime);v.put("bytes",normalized.length);v.put("width",w);v.put("height",h);db.insertWithOnConflict("media_assets",null,v,SQLiteDatabase.CONFLICT_IGNORE);db.setTransactionSuccessful();return new JSONObject().put("type","image").put("asset",id).put("newAsset",newAsset);
            }finally{db.endTransaction();}
        }finally{bitmap.recycle();}
    }
    static boolean exists(ChatStore s,String id){try(Cursor r=s.getReadableDatabase().rawQuery("SELECT 1 FROM media_assets WHERE id=?",new String[]{id})){return r.moveToFirst();}}
    static JSONObject sticker(ChatStore s,String id)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM stickers WHERE id=?",new String[]{id})){if(!r.moveToFirst())throw new IOException("表情包不存在");return new JSONObject(r.getString(0));}}
    static JSONObject addSticker(ChatStore s,String asset)throws Exception{asset(s,asset);String id="s-"+asset;try{return sticker(s,id);}catch(IOException ignored){}JSONObject row=new JSONObject().put("id",id).put("asset",asset).put("name","自定义表情包").put("category","未分类").put("description","").put("ocr","").put("meme","").put("emotion","").put("intent","").put("tone","").put("characters",new JSONArray()).put("enabled",true).put("deleted",false).put("favorite",false).put("uses",0).put("lastUsed",0);saveSticker(s,row);return row;}
    static void saveSticker(ChatStore s,JSONObject row)throws Exception{ContentValues v=new ContentValues();v.put("id",row.getString("id"));v.put("asset",row.getString("asset"));v.put("body",row.toString());s.getWritableDatabase().insertWithOnConflict("stickers",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static JSONArray library(ChatStore s,String query,String filter,int offset)throws Exception{List<JSONObject> rows=new ArrayList<>();try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM stickers",null)){while(r.moveToNext()){JSONObject e=new JSONObject(r.getString(0));if(e.optBoolean("deleted"))continue;if(!query.isEmpty()&&!e.toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;if(filter.equals("favorites")&&!e.optBoolean("favorite"))continue;if(filter.equals("recent")&&e.optLong("lastUsed")==0)continue;rows.add(e);}}rows.sort((a,b)->Long.compare(b.optLong("lastUsed"),a.optLong("lastUsed")));JSONArray out=new JSONArray();for(int i=Math.max(0,offset);i<Math.min(rows.size(),Math.max(0,offset)+60);i++)out.put(rows.get(i));return out;}
    static JSONObject updateSticker(ChatStore s,JSONObject args,Set<String> known)throws Exception{JSONObject row=sticker(s,args.getString("id"));for(String k:new String[]{"name","category","description","emotion","intent","tone","ocr","meme"})if(args.has(k))row.put(k,MediaData.cut(args.getString(k),k.equals("description")||k.equals("ocr")||k.equals("meme")?1500:120));if(row.optString("name").isEmpty())throw new IOException("请填写名称");for(String k:new String[]{"enabled","favorite","deleted"})if(args.has(k))row.put(k,args.getBoolean(k));if(args.has("characters")){JSONArray a=args.getJSONArray("characters");if(a.length()>known.size())throw new IOException("角色权限无效");for(int i=0;i<a.length();i++)if(!known.contains(a.getString(i)))throw new IOException("角色权限含未知编号");row.put("characters",a);}if(row.optBoolean("deleted"))s.getWritableDatabase().delete("stickers","id=?",new String[]{row.getString("id")});else saveSticker(s,row);return row;}
    static JSONObject profile(ChatStore s,String who)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM media_profiles WHERE character=?",new String[]{who})){return r.moveToFirst()?new JSONObject(r.getString(0)):new JSONObject().put("frequency","normal").put("emotions",new JSONArray()).put("preferred",new JSONArray()).put("blocked",new JSONArray()).put("style","");}}
    static JSONObject profile(ChatStore s,String who,JSONObject args)throws Exception{JSONObject p=profile(s,who);if(args.has("frequency")){String f=args.getString("frequency");if(!Arrays.asList("off","low","normal","high").contains(f))throw new IOException("频率无效");p.put("frequency",f);for(String k:new String[]{"preferred","blocked","emotions"}){JSONArray in=args.optJSONArray(k),a=new JSONArray();if(in!=null)for(int i=0;i<Math.min(20,in.length());i++)a.put(MediaData.cut(in.optString(i),80));p.put(k,a);}p.put("style",MediaData.cut(args.optString("style"),1000));ContentValues v=new ContentValues();v.put("character",who);v.put("body",p.toString());s.getWritableDatabase().insertWithOnConflict("media_profiles",null,v,SQLiteDatabase.CONFLICT_REPLACE);}return p;}
    static JSONObject analysis(ChatStore s,String key)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM media_analysis WHERE id=?",new String[]{key})){return r.moveToFirst()?new JSONObject(r.getString(0)):null;}}
    static void analysis(ChatStore s,String key,JSONObject data){ContentValues v=new ContentValues();v.put("id",key);v.put("body",data.toString());s.getWritableDatabase().insertWithOnConflict("media_analysis",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static JSONArray userBlocks(ChatStore s,JSONArray requested)throws Exception{JSONArray result=new JSONArray();MediaData.validate(requested,null);for(int i=0;i<requested.length();i++){JSONObject b=requested.getJSONObject(i);if(b.getString("type").equals("text"))result.put(new JSONObject().put("type","text").put("text",b.getString("text")));else{asset(s,b.getString("asset"));if(b.getString("type").equals("sticker")){JSONObject e=sticker(s,b.getString("stickerId"));if(!e.getString("asset").equals(b.getString("asset"))||e.optBoolean("deleted")||!e.optBoolean("enabled",true))throw new IOException("表情包已删除或禁用");result.put(MediaData.snapshot(e));}else {JSONObject image=new JSONObject().put("type","image").put("asset",b.getString("asset"));try{JSONObject known=MediaData.snapshot(sticker(s,"s-"+b.getString("asset")));if(MediaData.knownSticker(known))image=known.put("type","image").put("known_semantics",true);}catch(IOException ignored){}result.put(image);}}}return result;}
    static void used(ChatStore s,JSONArray blocks,long now)throws Exception{for(int i=0;i<blocks.length();i++){JSONObject b=blocks.getJSONObject(i);if(!b.optString("type").equals("sticker"))continue;try{JSONObject row=sticker(s,b.getString("stickerId"));row.put("uses",row.optLong("uses")+1).put("lastUsed",now);saveSticker(s,row);}catch(IOException ignored){}}}
    static JSONArray filterDelivery(ChatStore s,String who,JSONArray blocks,long now)throws Exception{
        if(blocks==null||blocks.length()==0)return new JSONArray();JSONArray result=new JSONArray();JSONObject pref=profile(s,who);
        boolean cooling=false;Set<String> recent=new HashSet<>();long gap=pref.optString("frequency").equals("low")?30*60000L:pref.optString("frequency").equals("high")?2*60000L:5*60000L;
        try(Cursor r=s.getReadableDatabase().rawQuery("SELECT content,sent_at FROM messages WHERE character=? AND role='assistant' AND content LIKE '%stickerId%' ORDER BY id DESC LIMIT 3",new String[]{who})){boolean first=true;while(r.moveToNext()){if(first&&now-r.getLong(1)<gap)cooling=true;first=false;if(now-r.getLong(1)>=30*60000L)continue;JSONArray a=MediaData.array(r.getString(0));for(int i=0;i<a.length();i++)recent.add(a.getJSONObject(i).optString("stickerId"));}}
        for(int i=0;i<blocks.length();i++){JSONObject b=blocks.getJSONObject(i);if(b.optString("type").equals("text"))result.put(b);else if(b.optString("type").equals("sticker"))try{JSONObject e=sticker(s,b.getString("stickerId"));if(!cooling&&!recent.contains(e.getString("id"))&&MediaData.allowed(e,pref,who)&&!pref.optString("frequency").equals("off"))result.put(MediaData.snapshot(e));}catch(IOException ignored){}}
        return result;
    }
    static JSONArray delivered(ChatStore s,String who,JSONArray blocks,long message,long now)throws Exception{
        if(blocks==null||blocks.length()==0)return new JSONArray();
        // The just-inserted row still has empty content, so it cannot count as its own cooldown.
        JSONArray result=filterDelivery(s,who,blocks,now);
        if(result.length()==0)throw new IOException("待发送表情包已不可用，请手动重试");ContentValues v=new ContentValues();v.put("content",result.toString());v.put("body",MediaReply.body(result));s.getWritableDatabase().update("messages",v,"id=?",new String[]{""+message});used(s,result,now);return result;
    }
    static Set<String> referenced(ChatStore s)throws Exception{Set<String> ids=new HashSet<>();try(Cursor r=s.getReadableDatabase().rawQuery("SELECT content FROM messages WHERE content<>'[]'",null)){while(r.moveToNext()){JSONArray a=MediaData.array(r.getString(0));for(int i=0;i<a.length();i++)if(MediaData.hash(a.getJSONObject(i).optString("asset")))ids.add(a.getJSONObject(i).getString("asset"));}}try(Cursor r=s.getReadableDatabase().rawQuery("SELECT asset FROM stickers",null)){while(r.moveToNext())ids.add(r.getString(0));}return ids;}
    static JSONObject backup(Context c,ChatStore s)throws Exception{Set<String> referenced=referenced(s);JSONArray assets=new JSONArray(),stickers=new JSONArray(),profiles=new JSONArray();int total=0;try(Cursor r=s.getReadableDatabase().rawQuery("SELECT id FROM media_assets",null)){while(r.moveToNext()){String id=r.getString(0);if(!referenced.contains(id))continue;JSONObject row=asset(s,id);byte[] bytes;try(InputStream in=open(c,s,id,false)){bytes=StoryFiles.read(in,MAX_IMAGE);}total+=bytes.length;if(total>MAX_BACKUP)throw new IOException("媒体超过12MB备份上限，请先清理不用的图片");assets.put(row.put("data",java.util.Base64.getEncoder().encodeToString(bytes)));}}try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM stickers",null)){while(r.moveToNext())stickers.put(new JSONObject(r.getString(0)));}try(Cursor r=s.getReadableDatabase().rawQuery("SELECT character,body FROM media_profiles",null)){while(r.moveToNext())profiles.put(new JSONObject().put("character",r.getString(0)).put("profile",new JSONObject(r.getString(1))));}return new JSONObject().put("assets",assets).put("stickers",stickers).put("profiles",profiles);}
    static Set<String> validateBackup(JSONObject root,Set<String> known)throws Exception{JSONObject media=root.getJSONObject("media");JSONArray assets=media.getJSONArray("assets");if(assets.length()>2000)throw new IOException("媒体数量过多");Set<String> ids=new HashSet<>();long bytes=0;for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);String id=a.getString("id");if(!MediaData.hash(id)||!ids.add(id)||!Arrays.asList("image/png","image/jpeg").contains(a.getString("mime")))throw new IOException("媒体资源索引无效");String b64=a.getString("data");if(b64.length()>MAX_IMAGE*4/3+8)throw new IOException("媒体过大");byte[] data=java.util.Base64.getDecoder().decode(b64);if(data.length==0||data.length>MAX_IMAGE||data.length!=a.getInt("bytes")||!MediaData.hash(data).equals(id)||a.getInt("width")<1||a.getInt("height")<1||a.getInt("width")>4096||a.getInt("height")>4096)throw new IOException("媒体校验失败");bytes+=data.length;if(bytes>MAX_BACKUP)throw new IOException("媒体备份过大");}Set<String> stickerIds=new HashSet<>();JSONArray stickers=media.getJSONArray("stickers");if(stickers.length()>2000)throw new IOException("表情包数量过多");for(int i=0;i<stickers.length();i++){JSONObject e=stickers.getJSONObject(i);if(!e.getString("id").equals("s-"+e.getString("asset"))||!stickerIds.add(e.getString("id"))||!ids.contains(e.getString("asset"))||e.toString().length()>10000)throw new IOException("表情包备份无效");JSONArray a=e.optJSONArray("characters");if(a!=null)for(int j=0;j<a.length();j++)if(!known.contains(a.getString(j)))throw new IOException("未知表情包权限");}JSONArray profiles=media.getJSONArray("profiles");if(profiles.length()>known.size())throw new IOException("角色媒体设置过多");Set<String> roles=new HashSet<>();for(int i=0;i<profiles.length();i++){JSONObject row=profiles.getJSONObject(i);if(!known.contains(row.getString("character"))||!roles.add(row.getString("character"))||row.getJSONObject("profile").toString().length()>6000)throw new IOException("角色媒体设置无效");}return ids;}
    static byte[] thumbnail(byte[] data,int width,int height,String mime)throws Exception{
        BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth!=width||options.outHeight!=height||!mime.equals(options.outMimeType)||(long)width*height>6000000L)throw new IOException("备份图片格式或像素与索引不符");options.inJustDecodeBounds=false;options.inSampleSize=1;while(Math.max(width,height)/options.inSampleSize>256)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,options);if(bitmap==null)throw new IOException("备份图片已损坏");try{ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.WEBP,85,out);return out.toByteArray();}finally{bitmap.recycle();}
    }
    static void restore(Context c,ChatStore s,JSONObject root)throws Exception{if(root.optInt("version")<17)return;JSONObject media=root.getJSONObject("media");JSONArray assets=media.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);byte[] data=java.util.Base64.getDecoder().decode(a.getString("data"));byte[] thumb=thumbnail(data,a.getInt("width"),a.getInt("height"),a.getString("mime"));atomic(file(c,a.getString("id"),false),data);atomic(file(c,a.getString("id"),true),thumb);ContentValues v=new ContentValues();v.put("id",a.getString("id"));v.put("mime",a.getString("mime"));v.put("bytes",data.length);v.put("width",a.getInt("width"));v.put("height",a.getInt("height"));s.getWritableDatabase().insertWithOnConflict("media_assets",null,v,SQLiteDatabase.CONFLICT_IGNORE);}JSONArray stickers=media.getJSONArray("stickers");for(int i=0;i<stickers.length();i++)saveSticker(s,stickers.getJSONObject(i));JSONArray profiles=media.getJSONArray("profiles");for(int i=0;i<profiles.length();i++){JSONObject row=profiles.getJSONObject(i);profile(s,row.getString("character"),row.getJSONObject("profile"));}}
}
